const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Signs Android release builds with the A-Z Globe release key.
 *
 * The key and its passwords live in <repo>/credentials/ (gitignored):
 *
 *   credentials/azglobe-release.jks
 *   credentials/release-signing.properties
 *     storeFile=azglobe-release.jks
 *     storePassword=…
 *     keyAlias=azglobe
 *     keyPassword=…
 *
 * `android/` is regenerated by `expo prebuild`, so the signing config is added
 * here rather than edited into build.gradle. When the properties file is absent
 * (a fresh clone, CI without secrets) release builds keep the template's debug
 * signing, so they still build — they just can't update an installed copy
 * signed with the real key, and Firebase phone sign-in won't recognise them.
 */
const MARKER = '// @azglobe release signing';

// app/build.gradle → android/ → apps/azglobe/ → apps/ → repo root
const PROPS_PATH = "rootProject.file('../../../credentials/release-signing.properties')";

function apply(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  const loader = [
    MARKER,
    `def azReleaseSigningFile = ${PROPS_PATH}`,
    'def azReleaseSigning = new Properties()',
    'if (azReleaseSigningFile.exists()) {',
    '    azReleaseSigningFile.withInputStream { azReleaseSigning.load(it) }',
    '}',
    '',
    'android {',
  ].join('\n');

  const releaseConfig = [
    'signingConfigs {',
    "        if (azReleaseSigning['storeFile']) {",
    '            release {',
    "                storeFile new File(azReleaseSigningFile.parentFile, azReleaseSigning['storeFile'])",
    "                storePassword azReleaseSigning['storePassword']",
    "                keyAlias azReleaseSigning['keyAlias']",
    "                keyPassword azReleaseSigning['keyPassword']",
    '            }',
    '        }',
  ].join('\n');

  const releaseBuildType =
    /(release \{\s*\n(?:\s*\/\/[^\n]*\n)*\s*)signingConfig signingConfigs\.debug/;

  if (!/^android \{/m.test(gradle) || !gradle.includes('signingConfigs {') || !releaseBuildType.test(gradle)) {
    throw new Error(
      'withReleaseSigning: app/build.gradle no longer has the expected shape — update the plugin.'
    );
  }

  return gradle
    .replace(/^android \{/m, loader)
    .replace('signingConfigs {', releaseConfig)
    .replace(
      releaseBuildType,
      "$1signingConfig azReleaseSigning['storeFile'] ? signingConfigs.release : signingConfigs.debug"
    );
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = apply(mod.modResults.contents);
    return mod;
  });
};
